# map result-id -> (opname, args) for the region around FNegate
def scan(path):
    data = open(path, 'rb').read()
    words = struct.unpack('<%dI' % (len(data)//4), data)
    i = 5
    ops = []
    while i < len(words):
        w = words[i]
        opcode = w & 0xFFFF
        wc = w >> 16
        ops.append((i, opcode, words[i+1:i+wc]))
        i += wc
    for idx, (pos, op, args) in enumerate(ops):
        if op == 103:
            print('=== FNegate at', pos, '=== last 8 instructions:')
            for j in range(max(0, idx-8), idx+1):
                p, o, a = ops[j]
                print('   ', NAMES.get(o, '?'+str(o)), list(a))
            # find what uses the FNegate result
            res = args[1]
            for j in range(idx+1, min(len(ops), idx+20)):
                p, o, a = ops[j]
                if res in list(a[1:]):
                    print('   ->used by', NAMES.get(o, '?'+str(o)), list(a))
                    break
scan('D:/Rust/steel-front/assets/mesh.spv')